def decode(pieces, sequence_length, model_file=None, model_proto=None,
           reverse=False, name=None):
  if model_file is None and model_proto is None:
    raise ValueError("Either model_file or model_proto must be set.")
  if model_file is not None:
    sp = spm.SentencePieceProcessor(model_file=model_file)
  else:
    sp = spm.SentencePieceProcessor(model_proto=model_proto)
  text = []
  for i in range(pieces.shape[0]):
    decoded_piece = sp.decode_pieces(pieces[i, :sequence_length[i]])
    if reverse:
      decoded_piece = decoded_piece[::-1]
    text.append("".join(decoded_piece))
  return text

