def pbkdf2_bin(data, salt, iterations=DEFAULT_PBKDF2_ITERATIONS, keylen=None, hashfunc=None):
    if hashfunc is None:
        hashfunc = hashlib.sha256
    if keylen is None:
        keylen = hashfunc().digest_size
    prf = lambda p, s: hmac.new(p, s, hashfunc).digest()
    def xor_strings(s1, s2):
        return bytes([x ^ y for (x, y) in zip(s1, s2)])
    def pbkdf2(data, salt, iterations, keylen, prf):
        assert iterations > 0
        assert keylen > 0
        hlen = len(prf(b'', b''))
        l = int(math.ceil(keylen / hlen))
        r = keylen - (l - 1) * hlen
        xor_strings = lambda s1, s2: bytes([x ^ y for (x, y) in zip(s1, s2)])
        key = b''
        for i in range(1, l + 1):
            fi = b''
            u = prf(data, salt + struct.pack('>i', i))
            for j in range(iterations - 1):
                u = prf(u, b'')
            fi += u
            key += xor_strings(key, fi)[:r]
        return key[:keylen]
    return pbkdf2(data, salt, iterations, keylen, prf)

