def complete_leaf_value(
    return_type,  # type: Union[GraphQLEnumType, GraphQLScalarType]
    path,  # type: List[Union[int, str]]
    result,  # type: Any
):
    # type: (...) -> Union[int, str, float, bool]
    """
    Complete a Scalar or Enum by serializing to a valid value, returning null if serialization is not possible.
    """
    if return_type.name == "Int":
        try:
            return int(result)
        except ValueError:
            return None
    elif return_type.name == "Float":
        try:
            return float(result)
        except ValueError:
            return None
    elif return_type.name == "String":
        return str(result)
    elif return_type.name == "Boolean":
        return bool(result)
    else:
        return None

