def linear_exprs(A, x, b=None, rref=False, Matrix=None):
    if b is None:
        b = np.zeros(len(x))
    A = np.array(A)
    b = np.array(b)
    x = np.array(x)
    if rref:
        if Matrix is None:
            from sympy import Matrix
        A = Matrix(np.column_stack((A, -b)))
        A = A.rref()[0]
        return [A[i, -1] for i in range(A.shape[0])]
    return np.dot(A, x) - b

