def gaps(args):
    """
    %prog gaps agpfile

    Print out the distribution of gapsizes. Option --merge allows merging of
    adjacent gaps which is used by tidy().
    """
    agpfile = args.agpfile
    merge = args.merge

    gaps = []
    with open(agpfile) as f:
        for line in f:
            if line.startswith('#'):
                continue
            fields = line.split()
            if fields[4].startswith('N'):
                gaps.append(int(fields[5]))

    if merge:
        gaps = [sum(gaps)]

    for gap in gaps:
        print(gap)

