def decode_complementarity(comp, control):

    """
    # comp can be either:
    - None
    - "a<=expr" where a is a controls
    - "expr<=a" where a is a control
    - "expr1<=a<=expr2"
    """
    if comp is None:
        return None
    if comp.startswith(control + "<="):
        return float(comp[len(control + "<="):])
    if comp.endswith("<=" + control):
        return float(comp[:comp.index("<=" + control)])
    if "<=" in comp:
        expr1, expr2 = comp.split("<=" + control + "<=")
        return float(expr1), float(expr2)
    raise ValueError("Invalid complementarity expression")

