def updateMigrationBlockStatus(self, migration_status=0, migration_block=None, migration_request=None):
        """
        migration_status:
        0=PENDING
        1=IN PROGRESS
        2=COMPLETED
        3=FAILED (will be retried)
        9=Terminally FAILED
        status change:
        0 -> 1
        1 -> 2
        1 -> 3
        1 -> 9
        are only allowed changes for working through migration.
        3 -> 1 allowed for retrying.

        """
        if migration_status == 0:
            if migration_block.status == 0:
                migration_block.status = 1
            else:
                raise ValueError("Invalid status change: 0 -> 1")
        elif migration_status == 1:
            if migration_block.status == 1:
                if migration_request.status == 2:
                    migration_block.status = 2
                elif migration_request.status == 3:
                    migration_block.status = 3
                elif migration_request.status == 9:
                    migration_block.status = 9
                else:
                    raise ValueError("Invalid status change: 1 -> 2, 1 -> 3, or 1 -> 9")
            else:
                raise ValueError("Invalid status change: 1 -> 2, 1 -> 3, or 1 -> 9")
        elif migration_status == 3:
            if migration_block.status == 3:
                migration_block.status = 1
            else:
                raise ValueError("Invalid status change: 3 -> 1")
        else:
            raise ValueError("Invalid migration_status")

