def image_request_response(self, path):
        """Parse image request and create response."""
        if not path:
            return None
        path_parts = path.split('/')
        if len(path_parts)!= 3:
            return None
        image_id = path_parts[1]
        size = path_parts[2]
        image = self.image_store.get(image_id)
        if not image:
            return None
        image_data = image.get_data()
