    If *simplify* is ``True``, return a simplified expression.

    If *conj* is ``True``, return a CNF.
    Otherwise, return a DNF.
    """
    n = len(xs)
    if n == 0:
        return True
    if n == 1:
        return xs[0]
    if simplify:
        return Majority(*(x for x in xs if x is not True), simplify=False, conj=conj)
    if conj:
        return Majority(*xs[:-1], simplify=False, conj=False) & xs[-1]
    return Majority(*xs[:-1], simplify=False, conj=True) | xs[-1]

