def _get_array_index(array_path):
    """Translates @first @last @1 @-1 expressions into an actual array index.

    :param str array_path: Array path in XJ notation.
    :rtype: int
    :return: Array index.
    """
    tokens = array_path.split()
    if tokens[0] == "@first":
        return 0
    elif tokens[0] == "@last":
        return -1
    elif tokens[0].startswith("@"):
        return int(tokens[0][1:]) - 1
    else:
        raise ValueError("Invalid array path")

def _distance_stats_sqr_fast_generic(x, y, dcov_function):
    """Compute the distance stats using the fast algorithm."""
    n = len(x)
    dcov_matrix = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            dcov_matrix[i, j] = dcov_function(x[i], y[j])
    dcov_vector = dcov_matrix.reshape(n * n)
    dcov_vector.sort()
    return dcov_vector[int(n * (n - 1) / 2)]

