def field_match(self, node_field, pattern_field):
        """
        Check if two fields match.

        Field match if:
            - If it is a list, all values have to match.
            - If if is a node, recursively check it.
            - Otherwise, check values are equal.
        """
        if isinstance(node_field, list) and isinstance(pattern_field, list):
            return all(self.field_match(node_value, pattern_value) for node_value, pattern_value in zip(node_field, pattern_field))
        elif isinstance(node_field, Node) and isinstance(pattern_field, Node):
            return self.match(node_field, pattern_field)
        else:
            return node_field == pattern_field

