def looping_call(f, sleep=5, inc_sleep=0, max_sleep=60, timeout=600,
                 exceptions=(), *args, **kwargs):
    start_time = time.time()
    while True:
        try:
            f(*args, **kwargs)
        except exceptions:
            pass
        sleep += inc_sleep
        if sleep > max_sleep:
            sleep = max_sleep
        if timeout and time.time() - start_time >= timeout:
            break
        time.sleep(sleep)

