        By default, it will capture ``Exception``

        >>> @client.capture_exceptions
        >>> def foo():
        >>>     raise Exception()

        >>> with client.capture_exceptions():
        >>>    raise Exception()

        You can also specify exceptions to be caught specifically

        >>> @client.capture_exceptions((IOError, LookupError))
        >>> def bar():
        >>>     ...

        >>> with client.capture_exceptions((IOError, LookupError)):
        >>>    ...

        ``kwargs`` are passed through to ``.captureException``.
        """
        if function_or_exceptions and not isinstance(function_or_exceptions, (tuple, list)):
            function_or_exceptions = (function_or_exceptions,)

        def decorator(f):
            def wrapper(*args, **kwargs):
                try:
                    return f(*args, **kwargs)
                except Exception as e:
                    if not function_or_exceptions or type(e) in function_or_exceptions:
                        self.captureException(e, **kwargs)
                    raise
            return wrapper

        if function_or_exceptions and callable(function_or_exceptions):
            return decorator(function_or_exceptions)
        else:
            return decorator

