def _jars_to_directories(self, target):
    """Extracts and maps jars to directories containing their contents.

    :returns: a set of filepaths to directories containing the contents of jar.
    """
    jars = set()
    directories = set()

    for root, _, files in os.walk(target):
        for file in files:
            if file.endswith('.jar'):
                jars.add(os.path.join(root, file))

    for jar in jars:
        directory = os.path.splitext(jar)[0] + '_dir'
        with zipfile.ZipFile(jar, 'r') as zip_ref:
            zip_ref.extractall(directory)
        directories.add(directory)

    return directories

