def beta_confidence_intervals(ci_X, ntrials, ci=0.95):
    Plow = np.empty(ci_X.shape)
    Phigh = np.empty(ci_X.shape)
    for i in range(ci_X.shape[0]):
        for j in range(ci_X.shape[1]):
            a = ci_X[i, j] * ntrials
            b = ntrials - a
            Plow[i, j] = beta.ppf((1 - ci) / 2, a, b)
            Phigh[i, j] = beta.ppf(1 - (1 - ci) / 2, a, b)

    return Plow, Phigh

