def match_url(self, path, method='GET'):
        """ Find a callback bound to a path and a specific HTTP method.
            Return (callback, param) tuple or (None, {}).
            method: HEAD falls back to GET. HEAD and GET fall back to ALL.
        """
        if method == 'HEAD':
            method = 'GET'
        elif method == 'GET':
            method = 'ALL'
        for rule, callback in self.rules:
            match = rule.match(path)
            if match and (method in rule.methods or 'ALL' in rule.methods):
                return callback, match.groupdict()
        return None, {}

