def _apply_correction_on_genes(genes,
                               pathway_column_names,
                               pathway_definitions):
    """Helper function to create the gene-to-pathway
    membership matrix and apply crosstalk correction on that
    matrix. Returns the crosstalk-corrected pathway definitions
    for the input `genes.`
    """
    gene_to_pathway_matrix = np.zeros((len(genes), len(pathway_column_names)))
    for i, gene in enumerate(genes):
        for j, pathway in enumerate(pathway_column_names):
            if gene in pathway_definitions[pathway]:
                gene_to_pathway_matrix[i, j] = 1
    corrected_pathway_definitions = {}
    for i, pathway in enumerate(pathway_column_names):
        corrected_pathway_definitions[pathway] = []
        for j, gene in enumerate(genes):
            if gene_to_pathway_matrix[j, i] == 1:
                corrected_pathway_definitions[pathway].append(gene)

    return corrected_pathway_definitions

