def score(self, measurement, output_format='array'):
        """
            Method to score/classify a measurement against the trained knn clusters

            :param measurement: the point to classify
            :type measurement: pandas.DataFrame
            :param output_format: the format to return the scores ('array' or 'str')
            :type output_format: string
            :return scores: the scores for a given test/point
            :rtype scores: np.array
        """
        if output_format not in ['array','str']:
            raise ValueError("Invalid output_format. Must be 'array' or'str'.")
        if self.clusters is None:
            raise ValueError("No trained clusters available. Train the model first.")
        if not isinstance(measurement, np.ndarray):
            measurement = np.array(measurement)
        if measurement.shape!= (self.n_features,):
            raise ValueError(f"Invalid measurement. Must be a 1D array with {self.n_features} elements.")
        scores = []
        for cluster in self.clusters:
            score = 0
            for i in range(self.n_features):
                if measurement[i] == cluster[i]:
                    score += 1
            scores.append(score)
        if output_format == 'array':
            return np.array(scores)
        else:
            return str(scores)

