        specified in order to access any secrets. Otherwise this method
        will raise a ``PermissionDenied`` exception.

        :return: A dictionary of secrets where key is the secret handle
            and value is the secret value.
        """
        if'secrets' not in self.process.resource_requirements:
            raise PermissionDenied('Process does not have secrets resource requirement')
        secrets = {}
        for field in self.input.fields:
            if field.type == 'basic:secret:':
                secrets[field.handle] = field.value
        return secrets

