def parseReaderConfig(self, confdict):
        """Parse a reader configuration dictionary.

        Examples:
        {
            Type: 23,
            Data: b'\x00'
        }
        {
            Type: 1023,
            Vendor: 25882,
            Subtype: 21,
            Data: b'\x00'
        }
        """
        if 'Type' not in confdict:
            raise ValueError('Missing "Type" key in configuration dictionary')
        if confdict['Type'] == 23:
            if 'Data' not in confdict:
                raise ValueError('Missing "Data" key in configuration dictionary')
            return {
                'Type': confdict['Type'],
                'Data': confdict['Data'],
            }
        elif confdict['Type'] == 1023:
            if 'Vendor' not in confdict:
                raise ValueError('Missing "Vendor" key in configuration dictionary')
            if 'Subtype' not in confdict:
                raise ValueError('Missing "Subtype" key in configuration dictionary')
            if 'Data' not in confdict:
                raise ValueError('Missing "Data" key in configuration dictionary')
            return {
                'Type': confdict['Type'],
                'Vendor': confdict['Vendor'],
                'Subtype': confdict['Subtype'],
                'Data': confdict['Data'],
            }
        else:
            raise ValueError(f'Unknown "Type" value: {confdict["Type"]}')

