def diff_summary(self, old, new, rel_path=None):
        """
        Provides a summarized output of a diff between two revisions
        (file, change type, file type)
        """
        diff = self.diff(old, new, rel_path)
        summary = {}
        for file in diff:
            change_type = diff[file]['change_type']
            file_type = diff[file]['file_type']
            summary[file] = {
                'change_type': change_type,
                'file_type': file_type
            }

        return summary

